-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/weather/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, BOX_W, ROW_H, GAP = 20, kit.W - 40, 56, 10
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

local __mods, __loaded = {}, {}
local function require(n)
  local v = __loaded[n]
  if v ~= nil then return v end
  local f = __mods[n]
  if not f then error('module not found: ' .. tostring(n)) end
  v = f()
  if v == nil then v = true end
  __loaded[n] = v
  return v
end

__mods['wx'] = function()
-- Weather pieces shared by the app (src/main.lua) and the lock screen (lockscreen.lua, which
-- carries its own copy: lock entries load alone): the forecast cache, WMO weather codes, and
-- drawing (icons, seven-segment digits for a large temperature).
--
-- forecast.txt (written by whoever fetched last): "key=value" lines --
--   place, updated (epoch), now_t, now_feel, now_code, now_hum, now_wind, unit (C|F),
--   h<k>=time;temp;rain%;code for the next hours, d<k>=date;code;min;max;rain% for the days.

local X = {}

-- WMO weather interpretation codes, as Open-Meteo gives them
function X.kind(code)
  code = tonumber(code) or 0
  if code == 0 then return 'sun', 'Clear' end
  if code == 1 then return 'sun', 'Mainly clear' end
  if code == 2 then return 'partly', 'Partly cloudy' end
  if code == 3 then return 'cloud', 'Overcast' end
  if code == 45 or code == 48 then return 'fog', 'Fog' end
  if code >= 51 and code <= 57 then return 'rain', 'Drizzle' end
  if code >= 61 and code <= 67 then return 'rain', code >= 65 and 'Heavy rain' or 'Rain' end
  if code >= 71 and code <= 77 then return 'snow', 'Snow' end
  if code >= 80 and code <= 82 then return 'rain', 'Showers' end
  if code == 85 or code == 86 then return 'snow', 'Snow showers' end
  if code >= 95 then return 'storm', 'Thunderstorm' end
  return 'cloud', 'Cloudy'
end

-- the forecast url: Open-Meteo, no key
function X.forecast_url(lat, lon, unit)
  return 'https://api.open-meteo.com/v1/forecast?latitude=' .. lat .. '&longitude=' .. lon ..
    '&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m' ..
    '&hourly=temperature_2m,precipitation_probability,weather_code' ..
    '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max' ..
    '&forecast_days=4&timezone=auto&wind_speed_unit=kmh' .. (unit == 'F' and '&temperature_unit=fahrenheit' or '')
end

local function r(x) return x and math.floor(x + 0.5) or nil end

-- Open-Meteo's answer (decoded JSON) -> the cache text
function X.cache_text(d, place, unit, now)
  local c = d.current or {}
  local out = { 'place=' .. place, 'unit=' .. unit, 'updated=' .. now,
                'now_t=' .. (r(c.temperature_2m) or ''), 'now_feel=' .. (r(c.apparent_temperature) or ''),
                'now_code=' .. (c.weather_code or 0), 'now_hum=' .. (r(c.relative_humidity_2m) or ''),
                'now_wind=' .. (r(c.wind_speed_10m) or '') }
  local h = d.hourly or {}
  local times = h.time or {}
  -- the hours from now (the current time's hour) on, 12 of them
  local cur = tostring(c.time or ''):sub(1, 13)
  local first = 1
  for i, t in ipairs(times) do if tostring(t):sub(1, 13) >= cur then first = i; break end end
  for k = 0, 11 do
    local i = first + k
    if times[i] then
      out[#out + 1] = 'h' .. k .. '=' .. tostring(times[i]):sub(12, 16) .. ';' .. (r((h.temperature_2m or {})[i]) or '') .. ';' ..
        ((h.precipitation_probability or {})[i] or '') .. ';' .. ((h.weather_code or {})[i] or 0)
    end
  end
  local dd = d.daily or {}
  for i, t in ipairs(dd.time or {}) do
    out[#out + 1] = 'd' .. (i - 1) .. '=' .. t .. ';' .. ((dd.weather_code or {})[i] or 0) .. ';' ..
      (r((dd.temperature_2m_min or {})[i]) or '') .. ';' .. (r((dd.temperature_2m_max or {})[i]) or '') .. ';' ..
      ((dd.precipitation_probability_max or {})[i] or '')
  end
  return table.concat(out, '\n')
end

function X.parse_cache(text)
  if not text then return nil end
  local t = {}
  for k, v in text:gmatch('([%w_]+)=([^\n]*)') do t[k] = v end
  if not t.place then return nil end
  local f = { place = t.place, unit = t.unit or 'C', updated = tonumber(t.updated), now_t = tonumber(t.now_t),
              now_feel = tonumber(t.now_feel), now_code = tonumber(t.now_code) or 0, now_hum = tonumber(t.now_hum),
              now_wind = tonumber(t.now_wind), hours = {}, days = {} }
  for k = 0, 11 do
    local v = t['h' .. k]
    if v then
      local tm, temp, rain, code = v:match('^([^;]*);([^;]*);([^;]*);([^;]*)$')
      if tm then f.hours[#f.hours + 1] = { time = tm, temp = tonumber(temp), rain = tonumber(rain), code = tonumber(code) or 0 } end
    end
  end
  for k = 0, 6 do
    local v = t['d' .. k]
    if v then
      local date, code, lo, hi, rain = v:match('^([^;]*);([^;]*);([^;]*);([^;]*);([^;]*)$')
      if date then f.days[#f.days + 1] = { date = date, code = tonumber(code) or 0, lo = tonumber(lo), hi = tonumber(hi), rain = tonumber(rain) } end
    end
  end
  return f
end

-- the weekday of a date "YYYY-MM-DD"
local DAYS = { 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat' }
function X.weekday(date)
  local y, m, d = date:match('^(%d+)-(%d+)-(%d+)')
  y, m, d = tonumber(y), tonumber(m), tonumber(d)
  if not y then return '' end
  if m < 3 then y, m = y - 1, m + 12 end
  local k = (d + (13 * (m + 1)) // 5 + y + y // 4 - y // 100 + y // 400) % 7      -- Zeller: 0 = Saturday
  return DAYS[(k + 6) % 7 + 1]
end

------------------------------------------------------------------ drawing

local function circle(gg, x, y, rad) pcall(function() gg:circle(x, y, rad) end) end

-- a weather icon in a box of size s at (x, y): a few lines each (the host draws ~1024 a screen)
function X.icon(gg, kind, x, y, s)
  local function cloud(cx, cy, w)
    local h = w * 0.55
    local pts = {}
    local shape = { 0.1, 1, 0.9, 1, 1, 0.75, 0.88, 0.45, 0.68, 0.42, 0.6, 0.1, 0.35, 0.05, 0.22, 0.35, 0.05, 0.5, 0, 0.8, 0.1, 1 }
    for i = 1, #shape, 2 do
      pts[#pts + 1] = math.floor(cx + shape[i] * w)
      pts[#pts + 1] = math.floor(cy + shape[i + 1] * h)
    end
    gg:polyline(pts)
  end
  if kind == 'sun' then
    local cx, cy, rad = x + s // 2, y + s // 2, s // 5
    circle(gg, cx, cy, rad); circle(gg, cx, cy, rad - 1)
    for k = 0, 7 do
      local a = k * math.pi / 4
      gg:line(math.floor(cx + math.cos(a) * rad * 1.5), math.floor(cy + math.sin(a) * rad * 1.5),
              math.floor(cx + math.cos(a) * rad * 2.2), math.floor(cy + math.sin(a) * rad * 2.2))
    end
  elseif kind == 'partly' then
    local cx, cy, rad = x + s * 0.35, y + s * 0.3, s // 7
    circle(gg, math.floor(cx), math.floor(cy), rad)
    for k = 0, 4 do
      local a = math.pi * (0.75 + k * 0.25)
      gg:line(math.floor(cx + math.cos(a) * rad * 1.5), math.floor(cy + math.sin(a) * rad * 1.5),
              math.floor(cx + math.cos(a) * rad * 2.2), math.floor(cy + math.sin(a) * rad * 2.2))
    end
    cloud(x + s * 0.2, y + s * 0.35, s * 0.75)
  elseif kind == 'fog' then
    for k = 0, 3 do gg:line(x + s // 8 + (k % 2) * 6, y + s // 3 + k * s // 8, x + s - s // 8 - (k % 2) * 6, y + s // 3 + k * s // 8) end
  else
    cloud(x + s * 0.08, y + s * 0.12, s * 0.84)
    local by = math.floor(y + s * 0.72)
    if kind == 'rain' then
      for k = 0, 2 do local lx = math.floor(x + s * (0.3 + k * 0.2)); gg:line(lx, by, lx - 5, by + s // 5) end
    elseif kind == 'snow' then
      for k = 0, 2 do
        local lx = math.floor(x + s * (0.3 + k * 0.2))
        gg:line(lx - 4, by + 6, lx + 4, by + 6); gg:line(lx, by + 2, lx, by + 10)
      end
    elseif kind == 'storm' then
      local lx = math.floor(x + s * 0.5)
      gg:polyline({ lx + 4, by - 2, lx - 6, by + s // 8, lx + 4, by + s // 8, lx - 6, by + s // 4 })
    end
  end
end

-- seven-segment digits for a large number: height h, segment thickness t
local SEG = { ['0'] = 'abcdef', ['1'] = 'bc', ['2'] = 'abged', ['3'] = 'abgcd', ['4'] = 'fgbc', ['5'] = 'afgcd',
              ['6'] = 'afgedc', ['7'] = 'abc', ['8'] = 'abcdefg', ['9'] = 'abcdfg', ['-'] = 'g' }
function X.big_number(gg, s, x, y, h)
  local w, t = h // 2, math.max(4, h // 10)
  local half = h // 2
  for ch in s:gmatch('.') do
    local seg = SEG[ch]
    if seg then
      for sg in seg:gmatch('.') do
        if sg == 'a' then gg:rect(x, y, w, t, { fill = true })
        elseif sg == 'b' then gg:rect(x + w - t, y, t, half, { fill = true })
        elseif sg == 'c' then gg:rect(x + w - t, y + half, t, h - half, { fill = true })
        elseif sg == 'd' then gg:rect(x, y + h - t, w, t, { fill = true })
        elseif sg == 'e' then gg:rect(x, y + half, t, h - half, { fill = true })
        elseif sg == 'f' then gg:rect(x, y, t, half, { fill = true })
        elseif sg == 'g' then gg:rect(x, y + half - t // 2, w, t, { fill = true }) end
      end
      x = x + w + t * 2
    end
  end
  return x
end
function X.big_width(s, h)
  local w, t = h // 2, math.max(4, h // 10)
  local n = 0
  for ch in s:gmatch('.') do if SEG[ch] then n = n + 1 end end
  return n * (w + t * 2)
end

return X
end

-- Weather for XTOS Licorice, API 2.9 (uses tools/gamekit and src/wx.lua). Needs Wi-Fi.
--
-- The forecast from Open-Meteo (free, no key): now, the next 12 hours and 4 days, for a place
-- found by name (Open-Meteo's geocoding). Kept in forecast.txt, so it opens at once and the lock
-- screen (lockscreen.lua, built by bundle.py from src/lock/lock.lua and wx.lua) can show it. The app
-- fetches again when the forecast is over 30 minutes old, or on Refresh.

local X = require('wx')
local W, H = kit.W, kit.H
local BTN_Y, BTN_H = 704, 64
local STALE_S = 30 * 60
local UA = 'XteinkLicoriceWeather/1.0 (https://github.com/omer-faruq/touch-licorice-apps)'

local cfg = { name = nil, lat = nil, lon = nil, unit = 'C', lock = false }
local fc = nil                  -- the forecast (X.parse_cache)
local screen = 'main'           -- main | places
local places = {}
local status, busy_label, ERR = nil, nil, nil

local function now_sec()
  local ok, t = pcall(function() return ctx.clock:now() end)
  return (ok and type(t) == 'table' and tonumber(t.epoch_sec)) and math.floor(tonumber(t.epoch_sec)) or 0
end
local function hhmm(epoch)
  local ok, t = pcall(function() return ctx.clock:now() end)
  if not epoch or not ok or type(t) ~= 'table' or not tonumber(t.hour) then return '' end
  -- the wall clock now, moved back by the age of the forecast
  local wall = tonumber(t.hour) * 3600 + (tonumber(t.minute) or 0) * 60 - (now_sec() - epoch)
  wall = wall % 86400
  return string.format('%02d:%02d', wall // 3600, (wall % 3600) // 60)
end

------------------------------------------------------------------ storage

local function save_cfg()
  kit.write('settings.txt', 'name=' .. (cfg.name or '') .. '\nlat=' .. (cfg.lat or '') .. '\nlon=' .. (cfg.lon or '') ..
    '\nunit=' .. cfg.unit .. '\nlock=' .. tostring(cfg.lock))
end
local function load_cfg()
  local t = kit.kv(kit.read('settings.txt'))
  cfg.name = (t.name and t.name ~= '') and t.name or nil
  cfg.lat, cfg.lon = tonumber(t.lat), tonumber(t.lon)
  cfg.unit = t.unit == 'F' and 'F' or 'C'
  cfg.lock = t.lock == 'true'
  fc = X.parse_cache(kit.read('forecast.txt'))
end

------------------------------------------------------------------ network

local function keep_wifi() pcall(function() ctx.net:keep_wifi(5 * 60 * 1000) end) end

local pending = nil
local function get(url, label, on_done)
  if pending then return end
  keep_wifi()
  busy_label, pending = label, { since = kit.now_ms() }
  local job = pending
  local ok, err = pcall(function()
    ctx.net:request({ url = url, method = 'GET', headers = { ['User-Agent'] = UA }, timeout_ms = 30000 }, function(c, resp)
      if pending ~= job then return end
      pending, busy_label = nil, nil
      local okh, e = pcall(function()
        if type(resp) ~= 'table' or type(resp.body) ~= 'string' then on_done(nil, 'no answer'); return end
        local code = tonumber(resp.status) or tonumber(resp.code)
        if code and code >= 400 then on_done(nil, 'HTTP ' .. code); return end
        local okj, data = pcall(function() return ctx.json:decode(resp.body) end)
        if not okj or type(data) ~= 'table' then on_done(nil, 'not JSON'); return end
        on_done(data)
      end)
      if not okh then status = 'Error: ' .. kit.short(tostring(e), 40) end
      kit.refresh()
    end)
  end)
  if not ok then pending, busy_label, status = nil, nil, 'Could not ask: ' .. kit.short(tostring(err), 30) end
end

local function refresh_forecast()
  if not cfg.lat then status = 'Choose a place first.'; return end
  get(X.forecast_url(cfg.lat, cfg.lon, cfg.unit), 'Getting the forecast...', function(d, err)
    if not d then status = 'Forecast failed: ' .. tostring(err); return end
    local text = X.cache_text(d, cfg.name, cfg.unit, now_sec())
    kit.write('forecast.txt', text)
    fc = X.parse_cache(text)
    status = nil
  end)
end

local function find_place(q)
  get('https://geocoding-api.open-meteo.com/v1/search?count=8&language=en&format=json&name=' ..
      q:gsub('[^A-Za-z0-9%-%._~]', function(c) return string.format('%%%02X', c:byte()) end),
      'Looking for ' .. kit.short(q, 20) .. '...', function(d, err)
    if not d then status = 'Search failed: ' .. tostring(err); return end
    places = {}
    for _k, p in ipairs(d.results or {}) do
      local where = {}
      if p.admin1 then where[#where + 1] = tostring(p.admin1) end
      if p.country then where[#where + 1] = tostring(p.country) end
      places[#places + 1] = { name = tostring(p.name), lat = tonumber(p.latitude), lon = tonumber(p.longitude),
                              where = table.concat(where, ', ') }
    end
    screen, status = 'places', (#places == 0 and 'No place by that name.' or nil)
  end)
end

local function ask_place()
  ctx.input:text({ title = 'Place (city or town)', text = '' }, function(c, s)
    if s and s:match('%S') then find_place(s) end
    kit.refresh()
  end)
end

------------------------------------------------------------------ lock screen

local function toggle_lock()
  local L = ctx.lockscreen
  cfg.lock = not cfg.lock
  save_cfg()
  if not L then status = 'This firmware has no app lock screen.'; return end
  local okd, isdef = pcall(function() return L:is_default() end)
  if cfg.lock then
    if not (okd and isdef == true) then pcall(function() L:set_default() end) end
    status = 'Lock screen: the forecast.'
  else
    if okd and isdef == true then pcall(function() L:clear_default() end) end
    status = 'Lock screen: off.'
  end
end

------------------------------------------------------------------ drawing

local function deg(v) return v and (tostring(v) .. '°') or '-' end

local function draw_main(gg)
  if not fc then
    gg:text(16, 16, 'Weather', { font = kit.font('large') })
    gg:text(16, 140, cfg.lat and 'Tap Refresh for the forecast.' or 'Tap Place to choose where.', { font = kit.font('medium') })
    return
  end
  gg:text(16, 12, kit.short(fc.place, 24), { font = kit.font('large') })
  gg:text(16, 50, 'updated ' .. hhmm(fc.updated) .. (now_sec() - (fc.updated or 0) > STALE_S and '  (old)' or ''), { font = kit.font('small') })
  gg:line(0, 80, W, 80)
  -- now: a big temperature, the icon and the details
  local kind, text = X.kind(fc.now_code)
  local temp = fc.now_t and tostring(fc.now_t) or '-'
  local x = X.big_number(gg, temp, 24, 104, 96)
  gg:text(x + 2, 100, '°' .. fc.unit, { font = kit.font('large') })
  X.icon(gg, kind, W - 140, 92, 120)
  gg:text(24, 212, text, { font = kit.font('large') })
  gg:text(24, 250, 'feels ' .. deg(fc.now_feel) .. '   humidity ' .. (fc.now_hum or '-') .. '%   wind ' .. (fc.now_wind or '-') .. ' km/h',
          { font = kit.font('small') })
  gg:line(0, 282, W, 282)
  -- the next 12 hours, every second hour
  local col = W // 6
  for k = 1, 6 do
    local h = fc.hours[(k - 1) * 2 + 1]
    if h then
      local cx = (k - 1) * col
      gg:text(cx + 10, 292, h.time, { font = kit.font('small') })
      X.icon(gg, (X.kind(h.code)), cx + 14, 316, 48)
      gg:text(cx + 14, 370, deg(h.temp), { font = kit.font('medium') })
      gg:text(cx + 14, 398, (h.rain or 0) .. '%', { font = kit.font('small') })
    end
  end
  gg:line(0, 428, W, 428)
  -- the days
  for k, d in ipairs(fc.days) do
    local y = 440 + (k - 1) * 62
    gg:text(16, y + 16, k == 1 and 'Today' or X.weekday(d.date), { font = kit.font('medium') })
    X.icon(gg, (X.kind(d.code)), 110, y + 4, 52)
    gg:text(180, y + 16, deg(d.lo) .. ' / ' .. deg(d.hi), { font = kit.font('medium') })
    gg:text(340, y + 18, 'rain ' .. (d.rain or 0) .. '%', { font = kit.font('small') })
  end
end

local function draw_places(gg)
  gg:text(16, 16, 'Choose the place', { font = kit.font('large') })
  gg:line(0, 80, W, 80)
  for k, p in ipairs(places) do
    local y = 90 + (k - 1) * 74
    gg:text(20, y + 6, kit.short(p.name, 30), { font = kit.font('medium') })
    gg:text(20, y + 36, kit.short(p.where, 46), { font = kit.font('small') })
    gg:line(16, y + 68, W - 16, y + 68)
  end
end

local function buttons()
  if screen == 'places' then return { 'Back', 'Search again' } end
  return { 'Refresh', 'Place', '°' .. (cfg.unit == 'C' and 'F' or 'C'), cfg.lock and 'Lock off' or 'Lock' }
end
local function button_rect(k, n)
  local bw = math.floor((W - 24 - (n - 1) * 8) / n)
  return 12 + (k - 1) * (bw + 8), BTN_Y, bw, BTN_H
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    if kit.modal() then kit.draw_modal(gg); return end
    if screen == 'places' then draw_places(gg) else draw_main(gg) end
    local line = busy_label or status or ERR
    if line then gg:text(12, BTN_Y - 30, kit.short(line, 48), { font = kit.font('small') }) end
    local bs = buttons()
    for k, b in ipairs(bs) do
      local x, y, bw, bh = button_rect(k, #bs)
      kit.button(gg, x, y, bw, bh, b, { font = 'medium' })
    end
  end)
  if not ok then pcall(function() gg:text(8, H - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  local bs = buttons()
  for k, b in ipairs(bs) do
    local bx, by, bw, bh = button_rect(k, #bs)
    if x >= bx and x < bx + bw and y >= by and y < by + bh then
      status = nil
      if b == 'Refresh' then refresh_forecast()
      elseif b == 'Place' or b == 'Search again' then ask_place()
      elseif b == 'Back' then screen = 'main'
      elseif b == 'Lock' or b == 'Lock off' then toggle_lock()
      else
        cfg.unit = cfg.unit == 'C' and 'F' or 'C'
        save_cfg()
        refresh_forecast()
      end
      return
    end
  end
  if screen == 'places' and y >= 90 then
    local p = places[(y - 90) // 74 + 1]
    if p then
      cfg.name, cfg.lat, cfg.lon = p.name, p.lat, p.lon
      save_cfg()
      screen = 'main'
      refresh_forecast()
    end
  end
end

function on_input(c, ev)
  ERR = nil
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then tap(ev.x or 0, ev.y or 0)
    elseif ev.type == 'key' and kit.key_accepted(ev) then
      if kit.modal() then
        if ev.key == 'back' and kit.modal().cancel then kit.modal().cancel() end
      elseif ev.key == 'back' and screen == 'places' then screen = 'main' end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return true
end

function on_load(c)
  local ok, e = pcall(load_cfg)
  if not ok then ERR = tostring(e) end
  -- an old forecast (or none) is fetched again at once
  if cfg.lat and (not fc or now_sec() - (fc.updated or 0) > STALE_S) then refresh_forecast() end
end
function on_leave() pcall(function() ctx.net:keep_wifi(1) end) end

if rawget(_G, '__TEST') then
  __TEST.api = { X = X, fc = function() return fc end, cfg = cfg, screen = function() return screen end,
                 places = function() return places end, status = function() return status end }
end
